/* =====================================================================
   EducaConecta V4 — camada sobre a V3 (app.js)
   1. Hierarquia de cadastros: Estado → Regional → Escola → Série → Turma → Turma por disciplina → Aluno
   2. Perfil Responsável (pais) com acompanhamento dos filhos
   3. Biblioteca por TEMA (metadados BNCC) com faces Aluno · Professor · Família
   4. Montagem de curso de reforço a partir do diagnóstico
   5. Tema transversal Educação Financeira (modelo de projetos transversais)
   Todos os dados são fictícios e gerados de forma determinística.
   ===================================================================== */

/* ---------- Utilidades ---------- */
function v4hash(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function v4rand(seed){let a=v4hash(seed);return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function rint(r,min,max){return min+Math.floor(r()*(max-min+1))}
function fmt(n){return Number(n).toLocaleString('pt-BR')}
function pb(v){if(v==null||isNaN(v))return '<span class="pct na">—</span>';const c=v<60?'low':v<75?'mid':'high';return `<span class="pct ${c}">${Math.round(v)}%</span>`}
function slug(s){return s.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-')}

/* ---------- Armazenamento local da V4 ---------- */
const V4KEY='educaconecta_v4_demo';
let v4db;try{v4db=JSON.parse(localStorage.getItem(V4KEY)||'{}')}catch(e){v4db={}}
v4db={courses:[],progress:{},builder:null,...v4db};
function v4save(){try{localStorage.setItem(V4KEY,JSON.stringify(v4db))}catch(e){}}

/* =====================================================================
   1. HIERARQUIA DE CADASTROS
   ===================================================================== */
const SEGS={
 EF1:{nome:'Ensino Fundamental — Anos Iniciais',curto:'Anos Iniciais',series:['1º ano','2º ano','3º ano','4º ano','5º ano'],
  disc:['Língua Portuguesa','Matemática','Ciências','História','Geografia','Arte','Educação Física'],
  regente:['Língua Portuguesa','Matemática','Ciências','História','Geografia']},
 EF2:{nome:'Ensino Fundamental — Anos Finais',curto:'Anos Finais',series:['6º ano','7º ano','8º ano','9º ano'],
  disc:['Língua Portuguesa','Matemática','Ciências','História','Geografia','Língua Inglesa','Arte','Educação Física'],regente:[]},
 EM:{nome:'Ensino Médio',curto:'Ensino Médio',series:['1ª série','2ª série','3ª série'],
  disc:['Língua Portuguesa','Matemática','Física','Química','Biologia','História','Geografia','Filosofia','Sociologia','Língua Inglesa','Arte','Educação Física'],regente:[]}
};
const REGIONAIS_CFG=[
 {id:'metro',nome:'Regional Metropolitana',escolas:[
   {id:'horizonte',nome:'Escola Municipal Horizonte',dep:'Municipal',segs:['EF1','EF2']},
   {id:'jardim',nome:'Colégio Estadual Jardim Azul',dep:'Estadual',segs:['EF1','EF2','EM']}]},
 {id:'norte',nome:'Regional Norte',escolas:[
   {id:'primavera',nome:'Escola Municipal Primavera',dep:'Municipal',segs:['EF1']},
   {id:'vale',nome:'Escola Municipal Vale Verde',dep:'Municipal',segs:['EF1','EF2']},
   {id:'rioclaro',nome:'Colégio Estadual Rio Claro',dep:'Estadual',segs:['EF2','EM']}]},
 {id:'sul',nome:'Regional Sul',escolas:[
   {id:'campobelo',nome:'Escola Municipal Campo Belo',dep:'Municipal',segs:['EF1','EF2']},
   {id:'serranova',nome:'Colégio Estadual Serra Nova',dep:'Estadual',segs:['EF1','EF2','EM']}]}
];
const FIRST=['Ana','Bruno','Carla','Davi','Eduarda','Felipe','Gabriela','Heitor','Isabela','João','Kauã','Larissa','Miguel','Nicole','Otávio','Pietra','Rafael','Sofia','Thiago','Valentina','Arthur','Beatriz','Caio','Laura','Lucas','Manuela','Matheus','Helena','Enzo','Alice','Gustavo','Lívia','Samuel','Yasmin','Daniel','Clara','Luiza','Bernardo','Cecília','Murilo'];
const LAST=['Silva','Santos','Oliveira','Lima','Pereira','Costa','Rodrigues','Almeida','Nascimento','Ferreira','Araújo','Ribeiro','Carvalho','Gomes','Martins','Rocha','Barbosa','Mendes','Freitas','Moreira','Cardoso','Teixeira','Dias','Campos'];
const TFIRST=['Ricardo','Patrícia','Fernando','Luciana','André','Juliana','Marcos','Cristina','Paulo','Renata','Sérgio','Adriana','Roberto','Simone','Fábio','Tatiana','Leandro','Vanessa','Eduardo','Cláudia','Rogério','Mônica','Alexandre','Denise'];
const DEMO={teacher:'Marina Alves',turmaAna:'horizonte-EF14A',turmaPedro:'horizonte-EF22B'};
const NET=(function build(){
 const force={'horizonte-EF14':3,'horizonte-EF22':2};
 const net={nome:'Estado Demonstrativo',regionais:[],turmas:[],escolas:[]};
 REGIONAIS_CFG.forEach(rg=>{
  const R={id:rg.id,nome:rg.nome,escolas:[]};
  rg.escolas.forEach(es=>{
   const E={id:es.id,nome:es.nome,dep:es.dep,regId:rg.id,segs:es.segs,series:[],profs:{}};
   if(es.id==='horizonte')E.profs['reg-'+DEMO.turmaAna]=DEMO.teacher;
   const prof=key=>{if(!E.profs[key]){const r=v4rand(E.id+key);E.profs[key]=TFIRST[rint(r,0,TFIRST.length-1)]+' '+LAST[rint(r,0,LAST.length-1)]}return E.profs[key]};
   const tr=v4rand(es.id);
   es.segs.forEach(sk=>{const S=SEGS[sk];
    S.series.forEach((sn,si)=>{
     const sid=es.id+'-'+sk+si;const nt=force[sid]||rint(tr,1,3);
     const SE={id:sid,nome:sn,seg:sk,escId:es.id,regId:rg.id,turmas:[]};
     for(let k=0;k<nt;k++){
      const letra='ABC'[k],tid=sid+letra,r=v4rand(tid);
      const T={id:tid,nome:sn+' '+letra,serie:sn,seg:sk,escId:es.id,regId:rg.id,serId:sid,alunos:rint(r,22,32),disc:[]};
      S.disc.forEach(d=>{
       const p=(sk==='EF1'&&S.regente.includes(d))?prof('reg-'+tid):prof(sk+'-'+d);
       const avaliado=d==='Língua Portuguesa'||d==='Matemática';
       T.disc.push({nome:d,prof:p,part:rint(r,58,95),des:avaliado?rint(r,46,84):null});
      });
      SE.turmas.push(T);net.turmas.push(T);
     }
     E.series.push(SE);
    });
   });
   R.escolas.push(E);net.escolas.push(E);
  });
  net.regionais.push(R);
 });
 /* Ajustes para coerência com a demonstração da V3 (5º A: 28 alunos, média 65% em Matemática) */
 const ana=net.turmas.find(t=>t.id===DEMO.turmaAna);if(ana){ana.alunos=28;ana.disc.forEach(d=>{if(d.nome==='Matemática')d.des=65;if(d.nome==='Língua Portuguesa')d.des=71})}
 return net;
})();
function turmaById(id){return NET.turmas.find(t=>t.id===id)}
function escolaById(id){return NET.escolas.find(e=>e.id===id)}
function regById(id){return NET.regionais.find(r=>r.id===id)}
function serieById(id){for(const e of NET.escolas){const s=e.series.find(s=>s.id===id);if(s)return s}return null}
function studentsOf(T){
 if(T._st)return T._st;
 const r=v4rand('st'+T.id),list=[],used=new Set(['Ana Souza','Pedro Souza']);
 for(let i=0;i<T.alunos;i++){let n,g=0;do{n=FIRST[rint(r,0,FIRST.length-1)]+' '+LAST[rint(r,0,LAST.length-1)];g++}while(used.has(n)&&g<50);used.add(n);list.push({nome:n,part:rint(r,45,100),des:{}})}
 T.disc.forEach(d=>{if(d.des!=null)list.forEach(s=>{s.des[d.nome]=Math.max(10,Math.min(100,Math.round(d.des+(r()-.5)*56)))})});
 if(T.id===DEMO.turmaAna){list[0].nome='Ana Souza';list[0].demo='ana';list[0].des['Matemática']=58}
 if(T.id===DEMO.turmaPedro){list[0].nome='Pedro Souza';list[0].demo='pedro';list[0].des['Matemática']=58;list[0].des['Língua Portuguesa']=74}
 list.sort((a,b)=>a.nome.localeCompare(b.nome,'pt'));T._st=list;return list;
}
function anaMath(){return cycle&&cycle.diagnostic?cycle.diagnostic.percent:58}
function agg(ts){
 let al=0,p=0,lp=0,lpw=0,ma=0,maw=0;const pr=new Set(),es=new Set();
 ts.forEach(t=>{al+=t.alunos;es.add(t.escId);p+=t.disc.reduce((s,d)=>s+d.part,0)/t.disc.length*t.alunos;
  t.disc.forEach(d=>{pr.add(t.escId+'|'+d.prof);if(d.nome==='Língua Portuguesa'){lp+=d.des*t.alunos;lpw+=t.alunos}if(d.nome==='Matemática'){ma+=d.des*t.alunos;maw+=t.alunos}})});
 return{turmas:ts.length,alunos:al,escolas:es.size,profs:pr.size,part:al?p/al:null,lp:lpw?lp/lpw:null,ma:maw?ma/maw:null};
}
function crumbText(T){const e=escolaById(T.escId),r=regById(T.regId);return `${NET.nome} › ${r.nome} › ${e.nome} › ${T.serie} › ${T.nome}`}
function hierDiagram(){return `<div class="hier">${['🗺️ Estado','🧭 Regional','🏫 Escola','📚 Etapa / Série','👥 Turma','📘 Turma por disciplina','🧑‍🎓 Aluno','👪 Responsável'].map((n,i)=>`${i?'<span class="arrow">→</span>':''}<span class="node">${n}</span>`).join('')}</div>`}

/* Gestor: explorador da rede */
state.np=state.np||{reg:null,esc:null,ser:null,tur:null};
function npSet(o){state.np={reg:null,esc:null,ser:null,tur:null,...o};render()}
function netCrumbs(){const n=state.np,parts=[[NET.nome,'{}']];
 if(n.reg)parts.push([regById(n.reg).nome,`{reg:'${n.reg}'}`]);
 if(n.esc)parts.push([escolaById(n.esc).nome,`{reg:'${n.reg}',esc:'${n.esc}'}`]);
 if(n.ser)parts.push([serieById(n.ser).nome,`{reg:'${n.reg}',esc:'${n.esc}',ser:'${n.ser}'}`]);
 if(n.tur)parts.push([turmaById(n.tur).nome,`{reg:'${n.reg}',esc:'${n.esc}',ser:'${n.ser}',tur:'${n.tur}'}`]);
 return `<div class="crumbs">${parts.map(([t,o],i)=>`${i?'<span>›</span>':''}<button class="${i===parts.length-1?'current':''}" onclick="npSet(${o})">${t}</button>`).join('')}</div>`}
function aggRow(cells,a,onclick){return `<tr class="${onclick?'clickable':''}" ${onclick?`onclick="${onclick}"`:''}>${cells.map(c=>`<td>${c}</td>`).join('')}<td class="num">${fmt(a.turmas)}</td><td class="num">${fmt(a.alunos)}</td><td class="num">${pb(a.part)}</td><td class="num">${pb(a.lp)}</td><td class="num">${pb(a.ma)}</td></tr>`}
function aggHead(cols){return `<thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}<th class="num">Turmas</th><th class="num">Alunos</th><th class="num">Participação</th><th class="num">Diag. LP</th><th class="num">Diag. MA</th></tr></thead>`}
function aggStats(a,extra){return `<div class="stats">${extra||stat(fmt(a.escolas),'Escolas')}${stat(fmt(a.turmas),'Turmas')}${stat(fmt(a.alunos),'Alunos cadastrados')}${stat(fmt(a.profs),'Professores')}</div>`}
function schools(){
 const n=state.np;let body='';
 if(n.tur){const T=turmaById(n.tur),st=studentsOf(T);
  body=`${aggStats(agg([T]),stat(T.seg==='EF1'?'Regente':'Por disciplina','Modelo de docência'))}<div><div class="panel"><h3>Turma por disciplina</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Componente</th><th>Professor(a)</th><th class="num">Participação</th><th class="num">Diagnóstico</th></tr></thead><tbody>${T.disc.map(d=>`<tr><td>${d.nome}</td><td>${d.prof}</td><td class="num">${pb(d.part)}</td><td class="num">${pb(d.des)}</td></tr>`).join('')}</tbody></table></div><p class="small-note">${T.seg==='EF1'?'Anos Iniciais: um(a) professor(a) regente responde pelos componentes principais; Arte e Educação Física podem ter especialistas.':'Anos Finais e Ensino Médio: cada componente tem sua turma-disciplina e seu professor.'}</p></div><div class="panel"><h3>Alunos (${st.length})</h3><div class="table-wrap" style="max-height:470px;overflow:auto"><table class="data-table"><thead><tr><th>Aluno</th><th class="num">Particip.</th><th class="num">LP</th><th class="num">MA</th></tr></thead><tbody>${st.map(s=>`<tr><td>${s.nome}${s.demo?' <span class="label">demo</span>':''}</td><td class="num">${pb(s.part)}</td><td class="num">${pb(s.des['Língua Portuguesa'])}</td><td class="num">${pb(s.demo==='ana'?anaMath():s.des['Matemática'])}</td></tr>`).join('')}</tbody></table></div></div></div>`;
 }else if(n.ser){const S=serieById(n.ser);
  body=`${aggStats(agg(S.turmas),stat(SEGS[S.seg].curto,'Etapa'))}<div class="panel"><h3>Turmas do ${S.nome}</h3><div class="table-wrap"><table class="data-table">${aggHead(['Turma','Docência'])}<tbody>${S.turmas.map(T=>aggRow([T.nome,T.seg==='EF1'?'Regente: '+T.disc[0].prof:T.disc.length+' componentes'],agg([T]),`npSet({reg:'${n.reg}',esc:'${n.esc}',ser:'${S.id}',tur:'${T.id}'})`)).join('')}</tbody></table></div></div>`;
 }else if(n.esc){const E=escolaById(n.esc),ts=NET.turmas.filter(t=>t.escId===E.id);
  body=`${aggStats(agg(ts),stat(E.dep,'Dependência'))}${E.segs.map(sk=>`<div class="panel"><h3>${SEGS[sk].nome}</h3><div class="table-wrap"><table class="data-table">${aggHead(['Série'])}<tbody>${E.series.filter(s=>s.seg===sk).map(S=>aggRow([S.nome],agg(S.turmas),`npSet({reg:'${n.reg}',esc:'${E.id}',ser:'${S.id}'})`)).join('')}</tbody></table></div></div>`).join('')}`;
 }else if(n.reg){const R=regById(n.reg);
  body=`${aggStats(agg(NET.turmas.filter(t=>t.regId===R.id)))}<div class="panel"><h3>Escolas da ${R.nome}</h3><div class="table-wrap"><table class="data-table">${aggHead(['Escola','Dependência','Etapas'])}<tbody>${R.escolas.map(E=>aggRow([E.nome,E.dep,E.segs.map(s=>SEGS[s].curto).join(' · ')],agg(NET.turmas.filter(t=>t.escId===E.id)),`npSet({reg:'${R.id}',esc:'${E.id}'})`)).join('')}</tbody></table></div></div>`;
 }else{
  body=`${aggStats(agg(NET.turmas))}<div class="panel"><h3>Regionais</h3><div class="table-wrap"><table class="data-table">${aggHead(['Regional','Escolas'])}<tbody>${NET.regionais.map(R=>aggRow([R.nome,R.escolas.length],agg(NET.turmas.filter(t=>t.regId===R.id)),`npSet({reg:'${R.id}'})`)).join('')}</tbody></table></div></div>`;
 }
 return `${intro('Rede e cadastros','Navegue pela estrutura da rede: clique em uma linha para descer de nível.',`<button class="btn secondary sm" onclick="toast('Importação simulada. Em produção: carga do sistema de gestão escolar da rede, com validação dos vínculos.')">⤓ Importar cadastros</button>`)}<div class="band"><h3>Hierarquia de cadastros</h3>${hierDiagram()}<p class="v4-note">Cada nível agrega os indicadores dos níveis abaixo. Cadastros e números fictícios, gerados para demonstração.</p></div>${netCrumbs()}${body}<p class="small-note">Participação = atividades online concluídas (não é frequência escolar). Diagnóstico = média de atividades da plataforma, não Saeb nem Ideb.</p>`;
}
function managerAnalytics(){
 const f=state.af=state.af||{reg:'',esc:'',seg:''};
 let ts=NET.turmas.filter(t=>(!f.reg||t.regId===f.reg)&&(!f.esc||t.escId===f.esc)&&(!f.seg||t.seg===f.seg));
 const a=agg(ts);
 const escolas=NET.escolas.filter(e=>!f.reg||e.regId===f.reg);
 let rows,label;
 if(f.esc){label='Série';const E=escolaById(f.esc);rows=E.series.filter(s=>!f.seg||s.seg===f.seg).map(S=>[S.nome,agg(S.turmas)])}
 else if(f.reg){label='Escola';rows=escolas.map(E=>[E.nome,agg(ts.filter(t=>t.escId===E.id))]).filter(r=>r[1].turmas)}
 else{label='Regional';rows=NET.regionais.map(R=>[R.nome,agg(ts.filter(t=>t.regId===R.id))]).filter(r=>r[1].turmas)}
 const att=rows.filter(([,x])=>(x.ma!=null&&x.ma<60)||(x.lp!=null&&x.lp<60));
 return `${intro('Inteligência educacional','Indicadores consolidados por regional, escola, etapa e série.')}<div class="filters"><select aria-label="Regional" onchange="state.af={reg:this.value,esc:'',seg:state.af.seg};render()"><option value="">Todas as regionais</option>${NET.regionais.map(R=>`<option value="${R.id}" ${f.reg===R.id?'selected':''}>${R.nome}</option>`).join('')}</select><select aria-label="Escola" onchange="state.af.esc=this.value;render()"><option value="">Todas as escolas</option>${escolas.map(E=>`<option value="${E.id}" ${f.esc===E.id?'selected':''}>${E.nome}</option>`).join('')}</select><select aria-label="Etapa" onchange="state.af.seg=this.value;render()"><option value="">Todas as etapas</option>${Object.entries(SEGS).map(([k,S])=>`<option value="${k}" ${f.seg===k?'selected':''}>${S.curto}</option>`).join('')}</select></div><div class="stats">${stat(fmt(a.escolas),'Escolas no filtro')}${stat(fmt(a.alunos),'Alunos')}${stat(pb(a.part),'Participação')}${stat(pb(a.ma),'Diagnóstico de Matemática')}</div><div class="dashcols"><div class="panel"><h3>Comparativo por ${label.toLowerCase()}</h3><div class="table-wrap"><table class="data-table">${aggHead([label])}<tbody>${rows.map(([n,x])=>aggRow([n],x)).join('')}</tbody></table></div><p class="small-note">Médias de atividades da plataforma. Não se trata de nota Saeb nem de índice Ideb oficial.</p></div><div class="panel"><h3>Pontos de atenção</h3>${att.length?att.map(([n,x])=>`<div class="list-row"><div><b>${n}</b><small>${x.ma!=null&&x.ma<60?'Matemática '+Math.round(x.ma)+'%':''}${x.ma!=null&&x.ma<60&&x.lp!=null&&x.lp<60?' · ':''}${x.lp!=null&&x.lp<60?'Língua Portuguesa '+Math.round(x.lp)+'%':''}</small></div><span class="label gold">Atenção</span></div>`).join(''):'<p>Nenhum agrupamento abaixo de 60% neste filtro.</p>'}<div class="detail-banner" style="margin-top:14px"><b>Cursos de reforço publicados</b><p>${v4db.courses.length?`${v4db.courses.length} curso(s) montado(s) por professores a partir de diagnósticos.`:'Nenhum curso de reforço publicado ainda na demonstração.'}</p></div></div></div><div class="panel"><h3>Habilidades em foco (amostra ilustrativa)</h3>${skillBars()}</div>`;
}

