function themeById(id){return THEMES.find(t=>t.id===id)}
function etapaOf(t){return /^[1-5]º/.test(t.ano)?'Anos Iniciais':/^[6-9]º/.test(t.ano)?'Anos Finais':'Ensino Médio'}
const ANOS=['2º ano','5º ano','6º ano','7º ano','8º ano','9º ano','Ensino Médio'];
const FRIENDLY={'Frações':'Entender e comparar frações','Geometria':'Reconhecer figuras geométricas','Operações':'Resolver problemas com as quatro operações','Grandezas':'Usar medidas (metro, quilo, litro)','Leitura':'Compreender o que lê','Porcentagem':'Calcular porcentagens','Equações':'Resolver equações'};
function lessonPlan(t){return [
 ['Abertura · 10 min',`Problematizar a partir de ${t.ctx}. Levantar o que a turma já sabe e registrar hipóteses.`],
 ['Desenvolvimento · 25 min',`${t.ativ} Trabalho em duplas, com mediação do professor e circulação pelas mesas.`],
 ['Sistematização · 10 min','Registro coletivo das conclusões no quadro e no caderno, com exemplos produzidos pela turma.'],
 ['Avaliação formativa · 5 min',`Ticket de saída com 3 questões rápidas sobre ${t.bncc.map(b=>b[0]).join(', ')}. Usar o resultado para reagrupar alunos e decidir a retomada.`]]}
const MATERIAIS=['Slides de apoio (modelo editável)','Folha de atividades imprimível','Banco com 5 questões autorais e gabarito comentado','Sugestões de adaptação (Desenho Universal para a Aprendizagem)','Vídeo curto para retomada em sala'];

/* Página pública da biblioteca */
state.lib=state.lib||{q:'',etapa:'',ano:'',comp:'',transv:'',aval:''};
function libFiltered(){const f=state.lib,q=f.q.toLowerCase();return THEMES.filter(t=>(!f.etapa||etapaOf(t)===f.etapa)&&(!f.ano||t.ano===f.ano)&&(!f.comp||t.comp===f.comp)&&(!f.transv||t.transv.includes(f.transv))&&(!f.aval||(t.aval||'').startsWith(f.aval))&&(!q||`${t.title} ${t.exp} ${t.unidade} ${t.objeto} ${t.bncc.map(b=>b.join(' ')).join(' ')} ${t.transv.join(' ')}`.toLowerCase().includes(q)))}
function themeCard(t,extra){return `<article class="card theme-card"><div class="icon">${t.emoji}</div><div class="theme-meta"><span class="label">${t.ano}</span><span class="label purple">${t.comp}</span>${t.bncc.map(b=>`<span class="label green">${b[0]}</span>`).join('')}${t.transv.map(x=>`<span class="label orange">${x}</span>`).join('')}</div><h3>${t.title}</h3><p>${t.exp.split('. ')[0]}.</p><div class="faces"><span>🧑‍🎓 Aluno</span><span>👩‍🏫 Professor</span><span>👪 Família</span></div><div class="card-bottom"><span class="muted">${t.unidade}</span>${extra||`<a class="link" href="#theme/${t.id}" onclick="event.preventDefault();openTheme('${t.id}')">Abrir tema →</a>`}</div></article>`}
function libResults(){const r=libFiltered();return `<p class="muted" style="margin:0 0 14px">${r.length} tema(s) encontrado(s)</p><div class="feature-grid">${r.map(t=>themeCard(t)).join('')}</div>${r.length?'':'<div class="empty">Nenhum tema encontrado. Experimente outros filtros.</div>'}`}
function libSel(key,label,opts){return `<select aria-label="${label}" onchange="state.lib.${key}=this.value;document.getElementById('lib-results').innerHTML=libResults()"><option value="">${label}</option>${opts.map(o=>`<option ${state.lib[key]===o?'selected':''}>${o}</option>`).join('')}</select>`}
function resourcesPage(){return `${pageHeader('Biblioteca de conteúdos','Temas BNCC para aluno, professor e família','Cada tema é uma unidade indexada por metadados BNCC, pronta para ser estudada pelo aluno, planejada pelo professor e combinada em cursos de reforço.')}<section class="section"><div class="container"><div class="band"><h3>Como a biblioteca é organizada</h3><div class="hier">${['Etapa','Ano/série','Componente','Unidade temática','Objeto de conhecimento','Habilidade BNCC','Tema'].map((n,i)=>`${i?'<span class="arrow">→</span>':''}<span class="node">${n}</span>`).join('')}</div><p class="v4-note">Cada tema tem três faces: conteúdo do aluno (explicação, vídeo, atividade, exercícios), plano de aula e materiais do professor, e orientações para a família. Temas são combinados para formar disciplinas ou cursos de reforço.</p></div><div class="filters"><input aria-label="Buscar temas" placeholder="Buscar por tema, habilidade ou código BNCC" value="${state.lib.q}" oninput="state.lib.q=this.value;document.getElementById('lib-results').innerHTML=libResults()">${libSel('etapa','Todas as etapas',['Anos Iniciais','Anos Finais','Ensino Médio'])}${libSel('ano','Todos os anos',ANOS)}${libSel('comp','Todos os componentes',['Matemática','Língua Portuguesa'])}${libSel('transv','Temas transversais',[EF])}${libSel('aval','Avaliação de referência',['Saeb 2º ano','Saeb 5º ano','Saeb 9º ano','Enem'])}</div><div id="lib-results">${libResults()}</div><div class="panel" style="margin-top:28px"><span class="label orange">TEMA TRANSVERSAL</span><h3 style="margin-top:12px">Educação Financeira em vários componentes</h3><p>Temas transversais da BNCC atravessam componentes e anos. A biblioteca marca esses temas e permite montar percursos que conectam Matemática, Língua Portuguesa e outras áreas — do 5º ano (porcentagens no dia a dia) ao Ensino Médio (orçamento e juros com planilhas).</p><p>Modelo de referência: projetos escolares que integram um tema transversal aos componentes, com aulas prontas, formação de professores e gestores, como faz o programa Aprender Valor, do Banco Central. O protótipo não possui vínculo nem integração com esse programa.</p><button class="btn sm" onclick="state.lib={q:'',etapa:'',ano:'',comp:'',transv:'${EF}',aval:''};render()">Ver temas de Educação Financeira →</button></div><p class="small-note" style="margin-top:20px">Códigos e descrições BNCC usados para prototipagem. Antes da publicação, validar cada tema com a equipe pedagógica e com a matriz de referência vigente.</p></div></section>`}

/* Página de um tema */
state.face=state.face||'aluno';
function openTheme(id,face){state.face=face||'aluno';go('theme',id)}
function themePage(){const t=themeById(state.tab)||THEMES[0];const f=state.face;
 const meta=[['Etapa',etapaOf(t)],['Ano/série',t.ano],['Componente',t.comp],['Unidade temática',t.unidade],['Objeto de conhecimento',t.objeto],['Habilidade(s) BNCC',t.bncc.map(b=>`<b>${b[0]}</b> — ${b[1]}`).join('<br>')],['Avaliação de referência',t.aval||'Avaliação formativa da rede'],['Tema transversal',t.transv.join(', ')||'—'],['Carga sugerida',t.dur+' aula(s)'],['Habilidade do diagnóstico',t.skill]];
 let face='';
 if(f==='aluno')face=`<div class="face-box"><b>📖 Explicação</b><p>${t.exp}</p></div><div class="face-box"><b>🎬 Vídeo</b><p>Vídeo curto (3 a 5 min) com exemplos de ${t.ctx}. <span class="muted">Conteúdo a produzir.</span></p></div><div class="face-box"><b>🧩 Atividade interativa</b><p>${t.ativ}</p></div><div class="face-box"><b>✅ Exercícios de fixação</b><p>5 questões autorais com correção automática e devolutiva por habilidade.</p></div><div class="face-box"><b>🏁 Resultado</b><p>Mini-avaliação de saída; o resultado volta para o professor e para o painel da família.</p></div>`;
 if(f==='prof')face=`<h3>Plano de aula</h3><p><b>Objetivo:</b> desenvolver ${t.bncc.map(b=>b[0]).join(', ')} — ${t.bncc[0][1]}</p><p><b>Duração:</b> ${t.dur} aula(s) de 50 min</p>${lessonPlan(t).map(([a,b])=>`<div class="plan-step"><b>${a}</b><span>${b}</span></div>`).join('')}<h3 style="margin-top:22px">Materiais complementares</h3>${MATERIAIS.map(m=>`<div class="list-row"><span>📎 ${m}</span><button class="btn ghost sm" onclick="toast('Download simulado: ${m}.')">Baixar</button></div>`).join('')}<div class="detail-banner" style="margin-top:16px"><b>Uso em recomposição</b><p>Indicado quando o diagnóstico aponta dificuldade em “${t.skill}”. Pode ser combinado com outros temas em um curso de reforço.</p><button class="btn sm" onclick="v4AddToBuilder('${t.id}')">Usar em curso de reforço →</button></div>`;
 if(f==='fam')face=`<div class="face-box"><b>👪 O que seu filho vai aprender</b><p>${FRIENDLY[t.skill]||t.title}: ${t.exp}</p></div><div class="face-box"><b>🏠 Como ajudar em casa</b><p>${t.fam}</p></div><div class="face-box"><b>🌱 Sinais de progresso</b><p>A criança explica com as próprias palavras, resolve exemplos do dia a dia e erra menos nas atividades do tema.</p></div>`;
 const rel=THEMES.filter(x=>x.id!==t.id&&(x.skill===t.skill||x.transv.some(y=>t.transv.includes(y)))).slice(0,3);
 return `${pageHeader(`${t.comp} · ${t.ano}`,`${t.emoji} ${t.title}`,t.bncc.map(b=>b[0]).join(' · ')+(t.transv.length?' · '+t.transv.join(', '):''))}<section class="section"><div class="container"><button class="btn ghost sm" onclick="go('resources')">← Biblioteca</button><div class="theme-layout" style="margin-top:20px"><div class="panel"><h3>Metadados BNCC</h3><table class="meta-table"><tbody>${meta.map(([a,b])=>`<tr><th>${a}</th><td>${b}</td></tr>`).join('')}</tbody></table></div><div class="panel"><div class="pill-tabs">${[['aluno','🧑‍🎓 Para o aluno'],['prof','👩‍🏫 Para o professor'],['fam','👪 Para a família']].map(([k,l])=>`<button class="${f===k?'active':''}" onclick="state.face='${k}';render()">${l}</button>`).join('')}</div>${face}</div></div>${rel.length?`<div class="section-head" style="margin-top:30px"><h2>Temas relacionados</h2></div><div class="feature-grid">${rel.map(x=>themeCard(x)).join('')}</div>`:''}<p class="small-note">Conteúdo ilustrativo para prototipagem; validar com a equipe pedagógica antes da publicação.</p></div></section>`}

/* =====================================================================
   4. MONTAGEM DE CURSO DE REFORÇO (Professor)
   ===================================================================== */
function weakSkills(){const out={};skills.filter(s=>s.value<60).forEach(s=>out[s.name]=[`Turma ${s.value}%`]);
 if(cycle.diagnostic)Object.entries(cycle.diagnostic.bySkill).forEach(([k,v])=>{if(v.correct/v.total<.6)(out[k]=out[k]||[]).push(`Ana ${v.correct}/${v.total}`)});return out}
function builderState(){const b=v4db.builder=v4db.builder||{turmaId:DEMO.turmaAna,comp:'Matemática',sel:null,title:'',publico:'grupo',prazo:'2 semanas'};
 if(!b.sel){const w=Object.keys(weakSkills());b.sel=w.map(k=>THEMES.find(t=>t.ano==='5º ano'&&t.comp===b.comp&&t.skill===k&&!t.transv.length)).filter(Boolean).map(t=>t.id)}return b}
function v4AddToBuilder(id){const b=builderState();const t=themeById(id);if(t&&t.ano!=='5º ano'){toast('Nesta demonstração, o curso de reforço é montado para o 5º ano A.');}if(!b.sel.includes(id))b.sel.push(id);v4save();selectRole('teacher');go('dashboard','builder');toast('Tema adicionado ao curso de reforço.')}
function bToggle(id){const b=builderState();b.sel=b.sel.includes(id)?b.sel.filter(x=>x!==id):[...b.sel,id];v4save();render()}
function bMove(i,d){const b=builderState(),j=i+d;if(j<0||j>=b.sel.length)return;[b.sel[i],b.sel[j]]=[b.sel[j],b.sel[i]];v4save();render()}
function bComp(c){const b=builderState();b.comp=c;b.sel=null;v4save();render()}
function grupoApoio(){return studentsOf(turmaById(DEMO.turmaAna)).filter(s=>(s.demo==='ana'?anaMath():s.des['Matemática'])<60).length}
function pick(t,b){const on=b.sel.includes(t.id);return `<label class="pick ${on?'on':''}"><input type="checkbox" ${on?'checked':''} onchange="bToggle('${t.id}')"><span><b>${t.emoji} ${t.title}</b><small>${t.bncc.map(x=>x[0]).join(', ')} · ${t.skill} · ${t.dur} aula(s)${t.transv.length?' · '+t.transv.join(', '):''}</small></span><a class="link" style="margin-left:auto;white-space:nowrap" href="#theme/${t.id}" onclick="event.preventDefault();event.stopPropagation();openTheme('${t.id}','prof')">Ver</a></label>`}
function builder(){const b=builderState(),w=weakSkills(),T=turmaById(b.turmaId);
 const pool=THEMES.filter(t=>t.ano===T.serie&&t.comp===b.comp);
 const sug=pool.filter(t=>w[t.skill]&&!t.transv.length),other=pool.filter(t=>!sug.includes(t)&&!t.transv.length),trans=THEMES.filter(t=>t.ano===T.serie&&t.transv.length);
 const sel=b.sel.map(themeById).filter(Boolean),aulas=sel.reduce((s,t)=>s+t.dur,0);
 const sk=[...new Set(sel.map(t=>t.skill))];const defTitle='Reforço de '+b.comp+(sk.length&&sk.length<=2?': '+sk.join(' e '):sk.length>2?': '+sk.slice(0,-1).join(', ')+' e '+sk[sk.length-1]:'')+' · '+T.nome;
 const pubOpts=[['turma',`Turma inteira (${T.alunos} alunos)`],['grupo',`Grupo de apoio — abaixo de 60% (${grupoApoio()} alunos)`],['ana','Aluna Ana Souza (individual)']];
 const mine=v4db.courses.filter(c=>c.turmaId===T.id);
 return `${intro('Montar curso de reforço','Combine temas da biblioteca a partir das habilidades em atenção no diagnóstico.')}<div class="crumbs"><button class="current">${crumbText(T)}</button></div><div class="builder-grid"><div><div class="panel"><span class="label">PASSO 1</span><h3 style="margin-top:10px">Habilidades em atenção</h3><div class="filters" style="margin-bottom:10px"><select aria-label="Componente" onchange="bComp(this.value)">${['Matemática','Língua Portuguesa'].map(c=>`<option ${b.comp===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="chips">${Object.keys(w).length&&b.comp==='Matemática'?Object.entries(w).map(([k,v])=>`<span class="chip warn">⚠️ ${k} · ${v.join(' · ')}</span>`).join(''):'<span class="chip">Sem habilidades abaixo de 60% neste componente — escolha temas livremente.</span>'}</div><p class="small-note">Fonte: diagnóstico da turma (ilustrativo) ${cycle.diagnostic?'e diagnóstico realizado pela aluna Ana nesta demonstração':'— faça o diagnóstico como Aluno para incluir o resultado individual'}.</p></div><div class="panel"><span class="label purple">PASSO 2</span><h3 style="margin-top:10px">Escolha os temas</h3>${sug.length?`<b>Sugeridos pelo diagnóstico</b><div style="margin:8px 0 16px">${sug.map(t=>pick(t,b)).join('')}</div>`:''}${other.length?`<b>Outros temas do ${T.serie} · ${b.comp}</b><div style="margin:8px 0 16px">${other.map(t=>pick(t,b)).join('')}</div>`:''}${trans.length?`<b>Temas transversais</b><div style="margin-top:8px">${trans.map(t=>pick(t,b)).join('')}</div>`:''}</div></div><div><div class="panel"><span class="label green">PASSO 3</span><h3 style="margin-top:10px">Organize e publique</h3><div class="form-row"><label for="b-title">Nome do curso</label><input id="b-title" value="${(b.title||defTitle).replace(/"/g,'&quot;')}" oninput="v4db.builder.title=this.value;v4save()"></div><div class="form-row"><label for="b-pub">Público</label><select id="b-pub" onchange="v4db.builder.publico=this.value;v4save()">${pubOpts.map(([k,l])=>`<option value="${k}" ${b.publico===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-row"><label for="b-prazo">Prazo</label><select id="b-prazo" onchange="v4db.builder.prazo=this.value;v4save()">${['1 semana','2 semanas','3 semanas','Até a reavaliação'].map(p=>`<option ${b.prazo===p?'selected':''}>${p}</option>`).join('')}</select></div><b>Sequência (${sel.length} temas · ${aulas} aulas)</b>${sel.length?sel.map((t,i)=>`<div class="order-row"><span class="n">${i+1}</span><span class="grow">${t.emoji} ${t.title}<br><small class="muted">${t.bncc[0][0]} · ${t.dur} aula(s)</small></span><button aria-label="Subir" onclick="bMove(${i},-1)">↑</button><button aria-label="Descer" onclick="bMove(${i},1)">↓</button><button aria-label="Remover" onclick="bToggle('${t.id}')">✕</button></div>`).join(''):'<p class="muted">Selecione ao menos um tema.</p>'}<div class="detail-banner" style="margin-top:14px"><b>Ao publicar</b><p>O curso aparece para os alunos em “Meu reforço”, para as famílias em “Reforço e atividades” e libera a atividade de reforço e a reavaliação no ciclo.</p></div><button class="btn" style="margin-top:14px;width:100%" ${sel.length?'':'disabled'} onclick="publishCourse()">Publicar curso de reforço →</button></div>${mine.length?`<div class="panel"><h3>Cursos publicados nesta turma</h3>${mine.map(c=>{const p=courseProgress(c);return `<div class="list-row"><div><b>${c.title}</b><small>${c.publicoLabel} · ${c.themes.length} temas · prazo ${c.prazo} · ${c.date}</small></div><span class="tag">Ana: ${p.done}/${p.total}</span></div>`}).join('')}</div>`:''}</div></div>`}
function publishCourse(){const b=builderState(),T=turmaById(b.turmaId);if(!b.sel.length)return;const el=document.getElementById('b-title');const w=weakSkills();const sel=b.sel.map(themeById);
 const title=(el&&el.value.trim())||('Reforço de '+b.comp+' · '+T.nome);
 const pubLabel={turma:'Turma inteira',grupo:'Grupo de apoio',ana:'Ana Souza'}[b.publico];
 const c={id:'c'+Date.now(),title,turmaId:T.id,turmaNome:T.nome,comp:b.comp,publico:b.publico,publicoLabel:pubLabel,prazo:b.prazo,themes:[...b.sel],date:new Date().toLocaleDateString('pt-BR'),skills:[...new Set(sel.map(t=>t.skill))]};
 v4db.courses.unshift(c);v4db.builder={...b,title:'',sel:null};v4save();
 cycle.reinforcement={title,group:T.nome,date:c.date,courseId:c.id};cycleEvent(`Professora publicou o curso “${title}” (${c.themes.length} temas)`);
 render();toast('Curso publicado. Acesse como Aluno ou Responsável para acompanhar.')}
function courseProgress(c){const p=v4db.progress[c.id]||{};const done=c.themes.filter(id=>p[id]).length;return{done,total:c.themes.length,pct:c.themes.length?Math.round(done/c.themes.length*100):0}}
function coursesFor(turmaId){return v4db.courses.filter(c=>c.turmaId===turmaId)}

/* =====================================================================
   ALUNO: Meu reforço
   ===================================================================== */
state.openTheme=state.openTheme||null;
function toggleDone(cid,tid){const p=v4db.progress[cid]=v4db.progress[cid]||{};p[tid]=!p[tid];v4save();const c=v4db.courses.find(x=>x.id===cid);if(p[tid])cycleEvent(`Ana concluiu o tema “${themeById(tid).title}”`);if(c&&courseProgress(c).done===c.themes.length&&p[tid])toast('Curso concluído! Faça a atividade de reforço e a reavaliação.');render()}
function studentReinforce(){const cs=coursesFor(DEMO.turmaAna);
 if(!cs.length)return `${intro('Meu reforço','Cursos montados pela sua professora a partir do diagnóstico.')}<div class="panel"><h3>Nenhum curso de reforço ainda</h3><p>Quando a professora publicar um curso com temas para você, ele aparecerá aqui.</p><button class="btn secondary sm" onclick="selectRole('teacher');go('dashboard','builder')">Ver como Professor: montar reforço →</button></div>`;
 return `${intro('Meu reforço','Estude os temas na ordem sugerida e marque cada um ao concluir.')}${cs.map(c=>{const p=courseProgress(c),pr=v4db.progress[c.id]||{};return `<div class="panel"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><span class="label purple">${c.comp}</span> <span class="label">${c.publicoLabel}</span><h3 style="margin:10px 0 4px">${c.title}</h3><small class="muted">Publicado em ${c.date} · prazo ${c.prazo}</small></div><div style="min-width:180px"><b>${p.done} de ${p.total} temas</b><div class="progress-track"><div class="progress-fill green" style="width:${p.pct}%"></div></div></div></div><div style="margin-top:16px">${c.themes.map((id,i)=>{const t=themeById(id),open=state.openTheme===c.id+id;return `<div class="theme-acc"><button onclick="state.openTheme=${open?'null':`'${c.id+id}'`};render()"><span><b>${i+1}. ${t.emoji} ${t.title}</b><br><small class="muted">${t.bncc[0][0]} · ${t.dur} aula(s)</small></span><span class="status ${pr[id]?'ok':'dev'}">${pr[id]?'Concluído':'A fazer'}</span></button>${open?`<div class="body"><div class="face-box"><b>📖 Explicação</b><p>${t.exp}</p></div><div class="face-box"><b>🎬 Vídeo</b><p>Vídeo curto com exemplos de ${t.ctx}.</p></div><div class="face-box"><b>🧩 Atividade</b><p>${t.ativ}</p></div><button class="btn sm" onclick="toggleDone('${c.id}','${id}')">${pr[id]?'Desmarcar':'Concluí este tema ✓'}</button> <a class="link" href="#theme/${id}" onclick="event.preventDefault();openTheme('${id}')">Abrir tema completo →</a></div>`:''}</div>`}).join('')}</div>${p.done===p.total?`<div class="detail-banner"><b>Curso concluído 🎉</b><p>Agora faça a atividade de reforço e a reavaliação no ciclo.</p><button class="btn sm" onclick="go('dashboard','cycle')">Ir para avaliação e recomposição →</button></div>`:''}</div>`}).join('')}`}

/* =====================================================================
   2. PERFIL RESPONSÁVEL (pais)
   ===================================================================== */
const CHILDREN={ana:{nome:'Ana Souza',turmaId:DEMO.turmaAna,emoji:'👧'},pedro:{nome:'Pedro Souza',turmaId:DEMO.turmaPedro,emoji:'👦'}};
state.child=state.child||'ana';
function stLabel(p){return p==null?['dev','Sem dados']:p<50?['need','Precisa de apoio']:p<75?['dev','Em desenvolvimento']:['ok','Consolidado']}
function childSkills(k){
 if(k==='pedro')return [['Porcentagem',50,null],['Equações',67,null],['Leitura',80,null]];
 if(!cycle.diagnostic)return [];
 return Object.entries(cycle.diagnostic.bySkill).map(([s,v])=>{const r=cycle.reassessment&&cycle.reassessment.bySkill[s];return [s,Math.round(v.correct/v.total*100),r?Math.round(r.correct/r.total*100):null]})}
function childCourses(k){if(k==='pedro')return [{id:'static-pedro',title:'Reforço: Porcentagens · 8º ano B',comp:'Matemática',publicoLabel:'Grupo de apoio',prazo:'3 semanas',date:'18/11/2026',themes:['t-por7','t-por8'],static:{'t-por7':true}}];return coursesFor(CHILDREN[k].turmaId)}
function childProg(c){if(c.static){const d=c.themes.filter(x=>c.static[x]).length;return{done:d,total:c.themes.length,pct:Math.round(d/c.themes.length*100)}}return courseProgress(c)}
function parentHeader(){return `<div class="child-cards">${Object.entries(CHILDREN).map(([k,c])=>{const T=turmaById(c.turmaId),cs=childCourses(k);return `<button class="child-card ${state.child===k?'selected':''}" onclick="state.child='${k}';render()"><div class="who"><span class="avatar">${c.emoji}</span><div><b>${c.nome}</b><br><small class="muted">${T.nome} · ${escolaById(T.escId).nome}</small></div></div><div style="margin-top:12px;display:flex;gap:6px;flex-wrap:wrap">${cs.length?`<span class="label purple">${cs.length} curso(s) de reforço</span>`:'<span class="label green">Sem reforço pendente</span>'}</div></button>`}).join('')}</div>`}
function parentPanel(){const k=state.child,c=CHILDREN[k],T=turmaById(c.turmaId),st=studentsOf(T).find(s=>s.demo===k),cs=childCourses(k),sk=childSkills(k),first=c.nome.split(' ')[0];
 const lastDiag=k==='ana'?(cycle.diagnostic?cycle.diagnostic.percent:null):58;
 if(state.tab==='evolution')return `${intro('Evolução',`Como ${first} está avançando, em linguagem simples.`)}${parentHeader()}<div class="panel"><h3>Habilidades acompanhadas</h3>${sk.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>O que está aprendendo</th><th class="num">Diagnóstico</th><th class="num">Reavaliação</th><th>Situação</th></tr></thead><tbody>${sk.map(([s,a,b])=>{const [cl,l]=stLabel(b??a);return `<tr><td><b>${FRIENDLY[s]||s}</b></td><td class="num">${pb(a)}</td><td class="num">${pb(b)}</td><td><span class="status ${cl}">${l}</span></td></tr>`}).join('')}</tbody></table></div>`:`<p>${first} ainda não fez o diagnóstico nesta demonstração. Entre como Aluno e realize o diagnóstico do ciclo para ver a evolução aqui.</p><button class="btn secondary sm" onclick="selectRole('student');go('dashboard','cycle')">Ver como Aluno →</button>`}<p class="small-note">Poucas questões não medem proficiência oficial. Use estas informações para conversar com a escola.</p></div><div class="panel"><h3>Participação por componente</h3>${T.disc.slice(0,5).map(d=>{const v=Math.max(35,Math.min(100,d.part+(st?st.part-75:0)/3));return `<div style="margin:12px 0"><div style="display:flex;justify-content:space-between"><b>${d.nome}</b><span>${Math.round(v)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${v}%"></div></div></div>`}).join('')}<p class="small-note">Participação em atividades online (ilustrativa), não frequência escolar.</p></div>`;
 if(state.tab==='reinforce')return `${intro('Reforço e atividades',`Cursos de reforço de ${first} e como ajudar em casa.`)}${parentHeader()}${cs.length?cs.map(cr=>{const p=childProg(cr),pr=cr.static||v4db.progress[cr.id]||{};return `<div class="panel"><span class="label purple">${cr.comp}</span><h3 style="margin:10px 0 4px">${cr.title}</h3><small class="muted">Publicado em ${cr.date} · prazo ${cr.prazo}</small><div style="margin:14px 0"><b>${p.done} de ${p.total} temas concluídos</b><div class="progress-track"><div class="progress-fill green" style="width:${p.pct}%"></div></div></div>${cr.themes.map(id=>{const t=themeById(id);return `<div class="face-box"><div style="display:flex;justify-content:space-between;gap:10px"><b>${t.emoji} ${t.title}</b><span class="status ${pr[id]?'ok':'dev'}">${pr[id]?'Concluído':'Em andamento'}</span></div><p><b>Como ajudar em casa:</b> ${t.fam}</p></div>`}).join('')}</div>`}).join(''):`<div class="panel"><h3>Nenhum reforço atribuído</h3><p>Quando a professora publicar um curso de reforço para ${first}, ele aparecerá aqui com dicas para apoiar em casa.</p><button class="btn secondary sm" onclick="selectRole('teacher');go('dashboard','builder')">Ver como Professor →</button></div>`}`;
 if(state.tab==='school')return `${intro('Escola e professores',crumbText(T))}${parentHeader()}<div class="dashcols"><div class="panel"><h3>Professores de ${first}</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Componente</th><th>Professor(a)</th><th></th></tr></thead><tbody>${T.disc.map(d=>`<tr><td>${d.nome}</td><td>${d.prof}</td><td><button class="btn ghost sm" onclick="toast('Mensagem simulada para ${d.prof}. Em produção: canal moderado pela escola.')">Mensagem</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h3>Comunicados</h3>${[['28/11','Reunião de pais e responsáveis — 18h'],['02/12','Reavaliação de Matemática da turma'],['10/12','Encerramento do semestre e devolutiva das avaliações']].map(([d,t])=>`<div class="list-row"><span class="tag">${d}</span><b>${t}</b></div>`).join('')}<p class="small-note">Comunicados fictícios.</p></div></div>`;
 const p0=cs[0]?childProg(cs[0]):null;
 return `${intro('Olá, Carla! 👋','Acompanhe a vida escolar dos seus filhos no EducaConecta.')}${parentHeader()}<div class="stats">${stat(st?Math.round(st.part)+'%':'—','Participação nas atividades')}${stat(lastDiag!=null?lastDiag+'%':'—','Último diagnóstico de Matemática')}${stat(cs.length,'Cursos de reforço')}${stat(p0?p0.done+'/'+p0.total:'—','Temas de reforço concluídos')}</div><div class="dashcols"><div class="panel"><h3>Resumo de ${first}</h3>${sk.length?sk.slice(0,4).map(([s,a,b])=>{const [cl,l]=stLabel(b??a);return `<div class="list-row"><b>${FRIENDLY[s]||s}</b><span class="status ${cl}">${l}</span></div>`}).join(''):`<p>${first} ainda não realizou o diagnóstico nesta demonstração.</p>`}<button class="btn sm" style="margin-top:14px" onclick="go('dashboard','evolution')">Ver evolução →</button></div><div class="panel"><h3>Próximos passos</h3>${cs.length?`<div class="detail-banner"><b>📘 ${cs[0].title}</b><p>${p0.done} de ${p0.total} temas concluídos. Veja como ajudar em casa.</p><button class="btn sm" onclick="go('dashboard','reinforce')">Abrir reforço →</button></div>`:`<p>Nenhum reforço pendente.</p>`}<div class="list-row"><span class="tag">28/11</span><b>Reunião de pais e responsáveis</b></div></div></div><div class="panel"><h3>Privacidade</h3><p>O responsável vê apenas os dados dos próprios filhos. O vínculo é validado pela escola, e informações de outros alunos nunca são exibidas. Dados fictícios nesta demonstração.</p></div>`}

