function teacherClass(){const T=turmaById(DEMO.turmaAna),mine=T.disc.filter(d=>d.prof===DEMO.teacher),others=T.disc.filter(d=>d.prof!==DEMO.teacher),st=studentsOf(T),a=agg([T]);
 return `${intro('Minha turma',crumbText(T))}<div class="stats">${stat(T.alunos,'Estudantes')}${stat(mine.length,'Componentes que leciono')}${stat(pb(a.part),'Participação')}${stat(pb(a.ma),'Diagnóstico de Matemática')}</div><div class="dashcols"><div class="panel"><h3>Alunos</h3><div class="table-wrap" style="max-height:470px;overflow:auto"><table class="data-table"><thead><tr><th>Aluno</th><th class="num">Particip.</th><th class="num">LP</th><th class="num">MA</th></tr></thead><tbody>${st.map(s=>`<tr><td>${s.nome}${s.demo?' <span class="label">demo</span>':''}</td><td class="num">${pb(s.part)}</td><td class="num">${pb(s.des['Língua Portuguesa'])}</td><td class="num">${pb(s.demo==='ana'?anaMath():s.des['Matemática'])}</td></tr>`).join('')}</tbody></table></div><p class="small-note">Dados fictícios. Participação refere-se a atividades online, não à frequência presencial.</p></div><div><div class="panel"><h3>Turma por disciplina</h3><b>Como regente</b>${mine.map(d=>`<div class="list-row"><span>${d.nome}</span>${pb(d.des??d.part)}</div>`).join('')}<b style="display:block;margin-top:14px">Outros professores da turma</b>${others.map(d=>`<div class="list-row"><span>${d.nome}</span><small>${d.prof}</small></div>`).join('')}</div><div class="panel"><h3>Ações</h3><button class="btn sm" onclick="go('dashboard','builder')">Montar curso de reforço →</button> <button class="btn secondary sm" onclick="go('dashboard','diagnostics')">Pontos de atenção</button></div></div></div>`}
function planning(){const T=turmaById(DEMO.turmaAna);const ts=THEMES.filter(t=>t.ano===T.serie);
 return `${intro('Planos e recursos',`Temas do ${T.serie} com plano de aula e materiais complementares.`,`<button class="btn secondary sm" onclick="go('resources')">Biblioteca completa →</button>`)}<div class="feature-grid">${ts.map(t=>themeCard(t,`<span style="display:flex;gap:6px"><button class="btn ghost sm" onclick="openTheme('${t.id}','prof')">Plano de aula</button><button class="btn ghost sm" onclick="v4AddToBuilder('${t.id}')">+ Reforço</button></span>`)).join('')}</div>`}

/* =====================================================================
   INTEGRAÇÃO NOS MENUS, PÁGINAS E RENDER
   ===================================================================== */
menus.student.splice(menus.student.findIndex(m=>m[0]==='cycle')+1,0,['reinforce','📘','Meu reforço']);
menus.teacher.splice(menus.teacher.findIndex(m=>m[0]==='cycle')+1,0,['builder','🧱','Montar reforço']);
menus.manager.forEach(m=>{if(m[0]==='schools'){m[1]='🗂️';m[2]='Rede e cadastros'}});
menus.parent=[['overview','🏠','Meus filhos'],['evolution','📈','Evolução'],['reinforce','📘','Reforço e atividades'],['school','🏫','Escola e professores']];

dashboard=function(){let role=menus[state.role]?state.role:'student';const roleTitle={student:'Aluno',teacher:'Professor',manager:'Gestor',parent:'Responsável'}[role];
 return `<div class="dash-layout"><aside class="sidebar"><small>Ambiente do ${roleTitle}</small>${menus[role].map(([t,e,l])=>`<button class="side-link ${state.tab===t?'active':''}" onclick="go('dashboard','${t}')"><span class="side-ico">${e}</span>${l}</button>`).join('')}<small>Trocar ambiente</small><button class="side-link" onclick="go('login')"><span class="side-ico">↔</span>Alternar perfil</button><button class="side-link" onclick="logout()"><span class="side-ico">↩</span>Sair</button></aside><main class="dash-main"><div class="sim-banner">🧪 Ambiente demonstrativo: nomes, escolas, notas e indicadores são fictícios. As interações funcionam localmente no navegador.</div>${role==='student'?studentPanel():role==='teacher'?teacherPanel():role==='parent'?parentPanel():managerPanel()}</main></div>`};
const v4Student=studentPanel;studentPanel=function(){if(state.tab==='reinforce')return studentReinforce();let h=v4Student();
 if(state.tab==='overview'){const cs=coursesFor(DEMO.turmaAna);const T=turmaById(DEMO.turmaAna);const ban=`<p class="muted" style="margin:-8px 0 16px">${crumbText(T)}</p>${cs.length?`<div class="detail-banner" style="margin-bottom:20px"><b>📘 Novo curso de reforço: ${cs[0].title}</b><p>${courseProgress(cs[0]).done} de ${cs[0].themes.length} temas concluídos.</p><button class="btn sm" onclick="go('dashboard','reinforce')">Estudar agora →</button></div>`:''}`;h=h.replace('<div class="stats">',ban+'<div class="stats">')}
 return h};
const v4Subjects=studentSubjects;studentSubjects=function(){const T=turmaById(DEMO.turmaAna);return v4Subjects().replace('<div class="course-grid">',`<div class="panel"><h3>Minhas turmas por disciplina · ${T.nome}</h3><p class="muted">${crumbText(T)}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Componente</th><th>Professor(a)</th></tr></thead><tbody>${T.disc.map(d=>`<tr><td>${d.nome}</td><td>${d.prof}</td></tr>`).join('')}</tbody></table></div></div><div class="course-grid">`)};
const v4Teacher=teacherPanel;teacherPanel=function(){if(state.tab==='builder')return builder();return v4Teacher()};
const v4Manager=managerPanel;managerPanel=function(){let h=v4Manager();if(state.tab==='overview'||!state.tab){const a=agg(NET.turmas);
 h=h.replace('Panorama demonstrativo da Rede Municipal Horizonte.',`Panorama demonstrativo do ${NET.nome}: ${NET.regionais.length} regionais e ${NET.escolas.length} escolas.`)
  .replace(/<div class="stats">[\s\S]*?Participação nas atividades<\/span><\/div><\/div>/,`<div class="stats">${stat(fmt(a.escolas),'Unidades escolares')}${stat(fmt(a.alunos),'Alunos cadastrados')}${stat(fmt(a.profs),'Professores')}${stat(Math.round(a.part)+'%','Participação nas atividades')}</div><div class="band"><h3>Estrutura da rede</h3>${hierDiagram()}<button class="btn sm" style="margin-top:14px" onclick="go('dashboard','schools')">Explorar rede e cadastros →</button></div>`)}return h};
assignReinforcement=function(){go('dashboard','builder')};
const v4CycleTeacher=cycleTeacher;cycleTeacher=function(){return v4CycleTeacher().replace('Proposta: trilha Frações no cotidiano, exercícios e registro de acompanhamento.',cycle.reinforcement?`Curso publicado: “${cycle.reinforcement.title}”.`:'Monte um curso de reforço combinando temas da biblioteca a partir das habilidades em atenção.').replace(/>(Reatribuir reforço|Atribuir reforço) →</,cycle.reinforcement?'>Montar novo reforço →<':'>Montar curso de reforço →<')};
const v4CycleStudent=cycleStudent;cycleStudent=function(){return v4CycleStudent().replace('A professora atribuiu a trilha Frações no cotidiano. Você pode praticar agora.',cycle.reinforcement?`A professora publicou o curso “${cycle.reinforcement.title}”. Estude os temas em Meu reforço e faça a atividade.`:'')};

roles=function(){return `<div class="container role-cards four">${[['student','blue','📖','Alunos','Aprender e praticar','Trilhas, temas, simulados e reforço para desenvolver habilidades.'],['teacher','purple','🎓','Professores','Ensinar e desenvolver','Planos de aula, diagnósticos e montagem de cursos de reforço.'],['manager','green','📊','Gestores','Acompanhar e decidir','Indicadores por estado, regional, escola, série e turma.'],['parent','orange','👪','Famílias','Acompanhar e apoiar','Evolução dos filhos, reforço atribuído e dicas para ajudar em casa.']].map(([r,c,e,t,sub,desc])=>`<article class="role-card ${c}" onclick="selectRole('${r}');go('dashboard')"><div class="round">${e}</div><h3>${t}</h3><b style="color:#5b748f">${sub}</b><p>${desc}</p><span class="link">Explorar ambiente →</span></article>`).join('')}</div>`};
login=function(){return `<section class="login-wrap"><div class="login-panel" style="max-width:980px"><div class="eyebrow" style="text-align:center">Acesso demonstrativo</div><h2>Qual ambiente deseja explorar?</h2><p style="text-align:center">Escolha um perfil. Não é necessário fornecer dados pessoais.</p><div class="persona-grid four">${[['student','🧑‍🎓','Aluno','Estudar e realizar atividades'],['teacher','👩‍🏫','Professor','Planejar, avaliar e intervir'],['manager','👨‍💼','Gestor','Acompanhar a rede'],['parent','👪','Responsável','Acompanhar os filhos']].map(([r,e,t,d])=>`<button class="persona ${state.role===r?'selected':''}" onclick="selectRole('${r}');render()"><div class="big">${e}</div><b>${t}</b><span class="muted">${d}</span></button>`).join('')}</div><div style="text-align:center"><button class="btn" onclick="selectRole(state.role||'student');go('dashboard')">Entrar na demonstração →</button></div><p class="login-note">Ambientes fictícios. Nenhum login, matrícula ou integração institucional é realizado.</p></div></section>`};
const v4Features=features;features=function(){return v4Features().replace('Trilhas, conteúdos e atividades para complementar o ensino presencial.','Temas BNCC com conteúdo para o aluno e cursos de reforço sob medida.').replace('Painéis e indicadores que apoiam decisões pedagógicas.','Indicadores por estado, regional, escola, série e turma.').replace('Planos de aula e objetos educacionais classificados por habilidade.','Biblioteca por temas com faces do aluno, do professor e da família.').replace('✨','👪').replace('Jornadas personalizadas','Famílias conectadas').replace('Experiências relevantes para cada perfil da comunidade escolar.','Responsáveis acompanham a evolução e o reforço dos filhos.')};
const v4Hero=hero;hero=function(){return v4Hero().replace('para alunos, professores e gestores.','para alunos, professores, gestores e famílias.').replace('▤ Recursos da BNCC','▤ Biblioteca BNCC')};
const v4Home=home;home=function(){return v4Home().replace('Explore as três experiências','Explore as quatro experiências')};
const v4Simple=simplePage;simplePage=function(type){return v4Simple(type).replace('selecione um dos três perfis demonstrativos','selecione um dos quatro perfis demonstrativos')};
const v4Header=header;header=function(){return v4Header().replace('>Recursos BNCC<','>Biblioteca BNCC<')};
function v4ExamNav(){const nav=document.getElementById('nav');if(!nav||[...nav.querySelectorAll('a')].some(a=>a.textContent==='Saeb · Enem · Encceja'))return;const a=document.createElement('a');a.href='#evaluation-public';a.textContent='Saeb · Enem · Encceja';a.onclick=function(e){e.preventDefault();go('evaluation-public')};const ref=[...nav.querySelectorAll('a')].find(x=>x.textContent==='Formação');nav.insertBefore(a,ref||null)}
const v4Render=render;render=function(){if(state.page==='theme'){A.innerHTML=header()+themePage()+footer();v4ExamNav();document.title='EducaConecta | '+(themeById(state.tab)||THEMES[0]).title;return}v4Render();
 if(state.page==='dashboard'&&state.tab==='cycle'&&state.role==='teacher'){const b=document.querySelector('.cycle-actions');if(b&&!b.querySelector('.v4-reset')){const x=document.createElement('button');x.className='btn ghost sm v4-reset';x.textContent='↻ Limpar cursos de reforço';x.onclick=function(){if(confirm('Apagar os cursos de reforço publicados nesta demonstração?')){v4db={courses:[],progress:{},builder:null};v4save();cycle.reinforcement=null;saveCycle();render()}};b.appendChild(x)}}};
const v4Reset=resetCycle;resetCycle=function(){v4Reset();if(!cycle.diagnostic&&!cycle.reinforcement){v4db={courses:[],progress:{},builder:null};v4save();render()}};

