(function(){const h=location.hash.slice(1).split('/');const pages=['home','about','resources','courses','news','help','login','dashboard','evaluation-public','exam-detail','exam-quiz','exam-result','theme'];if(pages.includes(h[0])){state.page=h[0];if(h[1])state.tab=decodeURIComponent(h[1])}render()})();
